using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorChatClient = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        var app = await _appHost.BuildAsync();
        await app.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();
        _evaluatorChatClient = app.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsRelevant()
    {
        // Arrange
        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is .NET Aspire?")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        // Evaluate
        var chatHistory = messages.Select(m => new ChatMessage(m.Role, m.Text)).ToList();
        var result = await EvaluateAsync(evaluators, chatHistory);

        // Assert
        foreach (var metric in result)
        {
            Assert.IsFalse(
                metric.Rating is not null && metric.Rating < EvaluationRating.Average,
                $"Metric '{metric.Name}' scored below average: {metric.Rating}");
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsGrounded()
    {
        // Arrange
        var evaluators = new IEvaluator[]
        {
            new GroundednessEvaluator(),
        };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that answers questions about .NET."),
            new(ChatRole.User, "What language does .NET primarily use?")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        // Evaluate
        var chatHistory = messages.Select(m => new ChatMessage(m.Role, m.Text)).ToList();
        var result = await EvaluateAsync(evaluators, chatHistory);

        // Assert
        foreach (var metric in result)
        {
            Assert.IsFalse(
                metric.Rating is not null && metric.Rating < EvaluationRating.Average,
                $"Metric '{metric.Name}' scored below average: {metric.Rating}");
        }
    }

    private async Task<IReadOnlyList<EvaluationMetric>> EvaluateAsync(
        IEnumerable<IEvaluator> evaluators,
        IList<ChatMessage> chatHistory)
    {
        var metrics = new List<EvaluationMetric>();

        foreach (var evaluator in evaluators)
        {
            var context = new EvaluatorContext(chatHistory, _evaluatorChatClient);
            var result = await evaluator.EvaluateAsync(context);
            metrics.AddRange(result);
        }

        return metrics;
    }
}

